text(await tools.exec_command({cmd:"cat > /app/output/door_plane.py <<'PY'
"""Estimate the visible door panel angle from calibrated depth only."""
from geometry import *
def cloud(cam,path):
    path,m,p=observation(path);c=m['cameras'][cam];T=np.array(c['cam2world_gl']);K=np.array(c['intrinsic_cv'])
    D=np.load(path/f'depth_{cam}.npy');D=D[-1] if D.ndim==3 else D
    v,u=np.indices(D.shape);xyz=np.stack([(u-K[0,2])*D/K[0,0],-(v-K[1,2])*D/K[1,1],-D],-1)
    return (xyz@T[:3,:3].T+T[:3,3]).reshape(-1,3)
def plane(path):
    P=np.concatenate([cloud(c,path) for c in ['robot0_agentview_left','robot0_agentview_right']])
    P=P[(P[:,1]>-3.48)&(P[:,1]<-3.05)&(P[:,2]>.2)&(P[:,2]<.59)&(P[:,0]>3.5)&(P[:,0]<4.02)]
    rng=np.random.default_rng(7);best=[]
    for _ in range(500):
        sample=P[rng.choice(len(P),3,replace=False)];A=np.c_[sample[:,1:3],np.ones(3)]
        try:v=np.linalg.solve(A,sample[:,0])
        except np.linalg.LinAlgError:continue
        if abs(v[0])>.1:continue
        mask=np.abs(P[:,0]-np.c_[P[:,1:3],np.ones(len(P))]@v)<.002
        if np.count_nonzero(mask)>len(best):best=P[mask]
    co=np.linalg.lstsq(np.c_[best[:,1:3],np.ones(len(best))],best[:,0],rcond=None)[0]
    print(path,'points',len(best),'x=ay+bz+c',co,'angle',np.rad2deg(np.arctan(-co[1])))
    return co
if __name__=='__main__':
 import sys
 for p in sys.argv[1:] or [Path('/app/runs/latest.txt').read_text()]:plane(p)
PY
